const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point([−119.02882425044682, 46.929987337866386]);
  const point2 = ee.Geometry.Point([−119.70997639198902, 43.19114225407087]);
  const date = '2015-11-29';
  const dateStart = ee.Date(date);
  const dateEnd = dateStart.advance(1, 'day');

  // 2. Data Acquisition - Try Landsat 8
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(dateStart, dateEnd)
    .filterBounds(point1.union(point2));

  let collectionSize = await collection.size().getInfo();
  console.log(`Landsat 8 Images found: ${collectionSize}`);

  if (collectionSize === 0) {
    // Try wider date range
    const dateStartWide = dateStart.advance(−3, 'day');
    const dateEndWide = dateStart.advance(3, 'day');
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(dateStartWide, dateEndWide)
      .filterBounds(point1.union(point2));

    collectionSize = await collection.size().getInfo();
    console.log(`Landsat 8 Images (±3 days): ${collectionSize}`);

    if (collectionSize === 0) {
      console.log('No images found for the specified date and locations.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Get the closest image
  const image = collection.sort('CLOUD_COVER').first();

  // 4. Extract QA_PIXEL band for cloud detection
  const qaPixel = image.select('QA_PIXEL');

  // Check if QA_PIXEL exists
  const bandNames = await image.bandNames().getInfo();
  console.log(`Available bands: ${bandNames.join(', ')}`);

  if (!bandNames.includes('QA_PIXEL')) {
    console.log('QA_PIXEL band not found.');
    console.log('<answer>D</answer>');
    return;
  }

  // 5. Sample cloud status at both points
  // Bit 3: Cloud (value 8), Bit 4: Cloud Shadow (value 16)
  const sample1 = await qaPixel.sample({
    region: point1,
    scale: 30,
    geometries: true
  }).first().get('QA_PIXEL').getInfo();

  const sample2 = await qaPixel.sample({
    region: point2,
    scale: 30,
    geometries: true
  }).first().get('QA_PIXEL').getInfo();

  if (sample1 === null || sample2 === null) {
    console.log('Could not extract QA values at one or both points.');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Point 1 QA_PIXEL: ${sample1}`);
  console.log(`Point 2 QA_PIXEL: ${sample2}`);

  // Check bits for cloud (bit 3 = 8) or cloud shadow (bit 4 = 16)
  const cloudBit = 8; // 2^3
  const shadowBit = 16; // 2^4

  const point1Cloudy = (sample1 & cloudBit) !== 0 || (sample1 & shadowBit) !== 0;
  const point2Cloudy = (sample2 & cloudBit) !== 0 || (sample2 & shadowBit) !== 0;

  console.log(`Point 1 (46.93, -119.03) cloudy/foggy: ${point1Cloudy}`);
  console.log(`Point 2 (43.19, -119.71) cloudy/foggy: ${point2Cloudy}`);

  // 6. Final Answer
  if (point1Cloudy && point2Cloudy) {
    console.log('Both locations are covered by clouds or fog.');
    console.log('<answer>A</answer>');
  } else {
    console.log('At least one location is NOT covered by clouds or fog.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
